files.src/total.js:
export function total(values) {
  if (values.length === 0) return 0;
  let sum = 0;
  for (const value of values) {
    if (typeof value !== "number" || !isFinite(value)) {
      throw new Error("nonnumeric or nonfinite entry");
    }
    sum += value;
  }
  return sum;
}

files.src/total.test.js:
import { total } from './total.js';

test('sums finite numbers', () => {
  expect(total([2, 3])).toBe(5);
  expect(total([-2, -3])).toBe(-5);
  expect(total([])).toBe(0);
});

test('rejects nonnumeric entries', () => {
  expect(() => total(['invalid'])).toThrow('nonnumeric or nonfinite entry');
  expect(() => total([NaN])).toThrow('nonnumeric or nonfinite entry');
  expect(() => total([Infinity])).toThrow('nonnumeric or nonfinite entry');
});

